export const AIVX_JS: string = "\n(function() {\n  // Active nav state on scroll\n  const sections = document.querySelectorAll('.section[id]');\n  const navLinks = document.querySelectorAll('.sidebar-nav a[href^=\"#\"]');\n\n  function updateNav() {\n    let current = '';\n    sections.forEach(function(section) {\n      const top = section.getBoundingClientRect().top;\n      if (top <= 120) current = section.getAttribute('id');\n    });\n    navLinks.forEach(function(link) {\n      link.classList.remove('active');\n      if (link.getAttribute('href') === '#' + current) {\n        link.classList.add('active');\n      }\n    });\n  }\n\n  window.addEventListener('scroll', updateNav, { passive: true });\n  updateNav();\n})();\n\n(function() {\n  // Sortable leaderboard — click a column header to sort. Numeric values sort\n  // numerically (after stripping non-digit chars); text values sort alphabetically.\n  var tbl = document.querySelector('.leaderboard');\n  if (!tbl) return;\n  var headers = tbl.querySelectorAll('thead th');\n  var sortDir = {};\n  headers.forEach(function(th, col) {\n    th.addEventListener('click', function() {\n      var tbody = tbl.querySelector('tbody');\n      var rows = Array.from(tbody.querySelectorAll('tr'));\n      var asc = sortDir[col] !== true;\n      sortDir = {};\n      sortDir[col] = asc;\n      headers.forEach(function(h) { h.classList.remove('sort-asc','sort-desc'); });\n      th.classList.add(asc ? 'sort-asc' : 'sort-desc');\n      rows.sort(function(a, b) {\n        var aCell = a.querySelectorAll('td')[col];\n        var bCell = b.querySelectorAll('td')[col];\n        var aText = aCell ? aCell.innerText.replace(/[^0-9.\\-]/g,'') : '';\n        var bText = bCell ? bCell.innerText.replace(/[^0-9.\\-]/g,'') : '';\n        var aNum = parseFloat(aText);\n        var bNum = parseFloat(bText);\n        if (!isNaN(aNum) && !isNaN(bNum)) {\n          return asc ? aNum - bNum : bNum - aNum;\n        }\n        return asc ? aText.localeCompare(bText) : bText.localeCompare(aText);\n      });\n      rows.forEach(function(r) { tbody.appendChild(r); });\n    });\n  });\n})();\n"
